import React, { useState } from "react";
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField,
    MenuItem,
    Button,
    Box,
    Tooltip,
    Alert,
} from "@mui/material";
import { useIntl, FormattedMessage } from 'react-intl';
import CONSTS from 'AppData/Constants';

const NewSecretDialog = ({ open, onClose, onCreate, mode }) => {
    const initialFormState = {
        description: "",
        expiryOption: "90",
        customDays: "",
    };

    const [isValid, setIsValid] = useState(false);
    const [form, setForm] = useState(initialFormState);
    const [error, setError] = useState(false);
    const [helperText, setHelperText] = useState(" ");
    const intl = useIntl();

    const handleKeyDown = (e) => {
        const allowedKeys = [
            "Backspace",
            "ArrowLeft",
            "ArrowRight",
            "Tab",
            "Delete",
        ];

        const isCtrlCmd = e.ctrlKey || e.metaKey;

        // Allow system shortcuts like Ctrl+C, Ctrl+V, Ctrl+A
        if (isCtrlCmd) {
            return;
        }

        // Allow navigation keys
        if (allowedKeys.includes(e.key)) {
            return;
        }

        // Allow digits only
        if (!/^[0-9]$/.test(e.key)) {
            e.preventDefault();
            showTemporaryError(
                intl.formatMessage({
                    id: "Shared.AppsAndKeys.Secrets.NewSecretDialog.error.digitsOnly",
                    defaultMessage: "Only digits (0–9) are allowed",
                })
            );
        } else {
            setError(false);
            setHelperText(" ");
        }
    };

    const handlePaste = (e) => {
        const paste = e.clipboardData.getData("text");

        // Allow only positive integers greater than 0
        if (!/^[1-9][0-9]*$/.test(paste)) {
            e.preventDefault();
            showTemporaryError(
                intl.formatMessage({
                    id: "Shared.AppsAndKeys.Secrets.NewSecretDialog.error.only.positive.numbers",
                    defaultMessage: "Only positive whole numbers are allowed",
                })
            );
        }
    };

    const handleCustomDaysChange = (e) => {
        let newValue = e.target.value;
        // Remove leading zeros: Change "05" to "5".
        // But allow "0" temporarily if the user is typing, or handle as empty.
        if (newValue.length > 1 && newValue.startsWith("0")) {
            newValue = newValue.replace(/^0+/, '');
        }
        setForm({ ...form, customDays: newValue });
        if (newValue === "" || /^[1-9][0-9]*$/.test(newValue)) {
            setError(false);
            setHelperText("");
            setIsValid(newValue !== "");
        } else {
            setIsValid(false);
            showTemporaryError(
                intl.formatMessage({
                    id: "Shared.AppsAndKeys.Secrets.NewSecretDialog.error.positive.whole.numbers",
                    defaultMessage: "Only positive whole numbers allowed",
                })
            );
        }
    };

    const showTemporaryError = (message) => {
        setError(true);
        setHelperText(message);
        setTimeout(() => {
            setError(false);
            setHelperText("");
        }, 2000);
    };

    const handleClose = () => {
        setForm(initialFormState);
        setIsValid(false); // Reset validity when closing
        onClose();
    };

    const handleSubmit = async () => {
        let expiryDays = 0;

        if (form.expiryOption === "custom") {
            expiryDays = parseInt(form.customDays || 0, 10);
        } else if (form.expiryOption !== "never") {
            expiryDays = parseInt(form.expiryOption, 10);
        }

        // Build payload conditionally — omit expiresInSeconds for "never"
        const payload = {
            description: form.description,
            ...(form.expiryOption !== "never" && {
                expiresInSeconds: expiryDays > 0 ? expiryDays * 24 * 60 * 60 : 0,
            }),
        };
        try {
            await onCreate(payload);
            // Reset form after creation
            setForm(initialFormState);
            onClose();
        } catch (e) {
            // Keep dialog open so user can correct/retry.
        }
    };

    // determine if Create button should be disabled
    const isCreateDisabled =
        form.expiryOption === "custom" ? !isValid : false;

    // determine tooltip message
    const tooltipTitle =
        form.expiryOption === "custom" && !isValid
            ? intl.formatMessage({
                id: "Shared.AppsAndKeys.Secrets.NewSecretDialog.valid.days.tooltip",
                defaultMessage: "Enter a valid number of days to enable creation",
            })
            : "";

    return (
        <Dialog data-testid="new-secret-dialog" open={open} onClose={handleClose} fullWidth maxWidth="sm">
            <DialogTitle>
                {mode === CONSTS.SECRET_DIALOG_MODES.KEY_GENERATION ? (
                    <FormattedMessage
                        id="Shared.AppsAndKeys.Secrets.NewSecretDialog.title.keygen"
                        defaultMessage="Generate Application Keys – Create Secret"
                    />
                ) : (
                    <FormattedMessage
                        id="Shared.AppsAndKeys.Secrets.NewSecretDialog.title.add"
                        defaultMessage="Create New Secret"
                    />
                )}
            </DialogTitle>
            <DialogContent>
                {mode === CONSTS.SECRET_DIALOG_MODES.KEY_GENERATION && (
                    <Alert severity="info" sx={{ mb: 2 }}>
                        <FormattedMessage
                            id="Shared.AppsAndKeys.Secrets.NewSecretDialog.context.keygen"
                            defaultMessage="You can provide a description and expiry time for the consumer secret being generated during this process"
                        />
                    </Alert>
                )}
                <Box display="flex" flexDirection="column" gap={2} mt={1}>
                    <TextField
                        data-testid="secret-description-input"
                        label={intl.formatMessage({
                            id: 'Shared.AppsAndKeys.Secrets.NewSecretDialog.description.label',
                            defaultMessage: 'Description (optional)',

                        })}
                        fullWidth
                        margin="normal"
                        size="medium"
                        value={form.description}
                        onChange={(e) =>
                            setForm({ ...form, description: e.target.value })
                        }
                    />
                    <TextField
                        data-testid="secret-expiry-select-field"
                        select
                        label={intl.formatMessage({
                            id: 'Shared.AppsAndKeys.Secrets.NewSecretDialog.expiry.time.label',
                            defaultMessage: 'Expiry Time',

                        })}
                        fullWidth
                        value={form.expiryOption}
                        onChange={(e) => {
                            const value = e.target.value;
                            // Reset state properly based on selection
                            if (value === "custom") {
                                setForm({ ...form, expiryOption: value, customDays: "" }); // reset input
                                setIsValid(false); // must enter a new value
                            } else {
                                setForm({ ...form, expiryOption: value }); // normal selection
                                setIsValid(true); // predefined values are always valid
                            }
                        }}
                        SelectProps={{
                            'data-testid': 'secret-expiry-select',
                            MenuProps: {
                                MenuListProps: {
                                    'data-testid': 'secret-expiry-options-list',
                                },
                            },
                        }}
                    >
                        <MenuItem data-testid="secret-expiry-option-30" value="30">
                            <FormattedMessage
                                id="Shared.AppsAndKeys.Secrets.NewSecretDialog.expiry.time.30days"
                                defaultMessage="30 days" />
                        </MenuItem>
                        <MenuItem data-testid="secret-expiry-option-60" value="60">
                            <FormattedMessage
                                id="Shared.AppsAndKeys.Secrets.NewSecretDialog.expiry.time.60days"
                                defaultMessage="60 days" />
                        </MenuItem>
                        <MenuItem data-testid="secret-expiry-option-90" value="90">
                            <FormattedMessage
                                id="Shared.AppsAndKeys.Secrets.NewSecretDialog.expiry.time.90days"
                                defaultMessage="90 days" />
                        </MenuItem>
                        <MenuItem data-testid="secret-expiry-option-180" value="180">
                            <FormattedMessage
                                id="Shared.AppsAndKeys.Secrets.NewSecretDialog.expiry.time.180days"
                                defaultMessage="180 days" />
                        </MenuItem>
                        <MenuItem data-testid="secret-expiry-option-never" value="never">
                            <FormattedMessage
                                id="Shared.AppsAndKeys.Secrets.NewSecretDialog.expiry.time.never"
                                defaultMessage="Never Expires" />
                        </MenuItem>
                        <MenuItem data-testid="secret-expiry-option-custom" value="custom">
                            <FormattedMessage
                                id="Shared.AppsAndKeys.Secrets.NewSecretDialog.expiry.time.custom"
                                defaultMessage="Custom" />
                        </MenuItem>
                    </TextField>

                    {form.expiryOption === "custom" && (
                        <TextField
                            data-testid="secret-custom-days-input"
                            label={intl.formatMessage({
                                id: 'Shared.AppsAndKeys.Secrets.NewSecretDialog.custom.expiry.time.label',
                                defaultMessage: 'Custom Expiry Time (days)',
                            })}
                            type="number"
                            fullWidth
                            value={form.customDays}
                            onChange={handleCustomDaysChange}
                            onPaste={handlePaste}
                            onKeyDown={handleKeyDown}
                            error={error}
                            helperText={helperText}
                            inputProps={{
                                min: 1, // ensures spinner doesn’t go below 1
                                step: 1, // integer only
                            }}
                        />
                    )}
                </Box>
            </DialogContent>
            <DialogActions>
                <Button onClick={handleClose}>
                    <FormattedMessage
                        id='Shared.AppsAndKeys.Secrets.NewSecretDialog.cancel.button'
                        defaultMessage='Cancel'
                    />
                </Button>

                {/* Wrap button in Tooltip to show reason when disabled */}
                <Tooltip title={tooltipTitle} disableHoverListener={!isCreateDisabled}>
                    <span>
                        <Button
                            data-testid="create-secret-button"
                            variant="contained"
                            onClick={handleSubmit}
                            disabled={isCreateDisabled}
                        >
                            <FormattedMessage
                                id='Shared.AppsAndKeys.Secrets.NewSecretDialog.create.button'
                                defaultMessage='Create'
                            />
                        </Button>
                    </span>
                </Tooltip>
            </DialogActions>
        </Dialog>
    );
};

export default NewSecretDialog;
